import{_ as s,o as t,c as e,a2 as i}from"./chunks/framework.CDU0sSpB.js";const k=JSON.parse('{"title":"Data, backup, and restore","description":"Local data layout, encrypted backup, restore boundaries, and global stop.","frontmatter":{"title":"Data, backup, and restore","description":"Local data layout, encrypted backup, restore boundaries, and global stop.","outline":[2,3]},"headers":[],"relativePath":"en/guide/data.md","filePath":"en/guide/data.md","lastUpdated":null}'),n={name:"en/guide/data.md"};function d(r,a,l,h,p,o){return t(),e("div",null,[...a[0]||(a[0]=[i(`<h1 id="data-backup-and-restore" tabindex="-1">Data, backup, and restore <a class="header-anchor" href="#data-backup-and-restore" aria-label="Permalink to &quot;Data, backup, and restore&quot;">​</a></h1><p class="lead">The source of truth is the local SQLite event log. The interface, statistics, and notifications are rebuilt from records, so backing up the database matters more than backing up page state.</p><h2 id="data-layout" tabindex="-1">Data layout <a class="header-anchor" href="#data-layout" aria-label="Permalink to &quot;Data layout&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th><th>In encrypted backup</th></tr></thead><tbody><tr><td><code>.hearth/hearth.sqlite</code></td><td>Tasks, runs, approvals, effects, memory, methods, sync, events</td><td>Yes</td></tr><tr><td><code>.hearth/model-settings.json</code></td><td>Chat-model configuration and key</td><td>Included as encrypted metadata</td></tr><tr><td><code>.hearth/master.key</code></td><td>Local master key</td><td>Included after encryption</td></tr><tr><td><code>.hearth/workspaces/</code></td><td>Isolated task workspaces</td><td>No</td></tr><tr><td><code>.hearth/artifacts/</code></td><td>Managed artifacts</td><td>No</td></tr><tr><td><code>.hearth/outbox/</code></td><td>Local outbox and receipts</td><td>No</td></tr><tr><td><code>.hearth/backups/</code></td><td>Encrypted backup archives</td><td>No</td></tr><tr><td><code>.hearth/sources/</code></td><td>Source content snapshots</td><td>No</td></tr><tr><td><code>.hearth/device-frames/</code></td><td>Desktop observation frames</td><td>No</td></tr><tr><td><code>eval/runs/</code></td><td>Phase-one acceptance runs and artifacts</td><td>No</td></tr></tbody></table><h2 id="encrypted-backup" tabindex="-1">Encrypted backup <a class="header-anchor" href="#encrypted-backup" aria-label="Permalink to &quot;Encrypted backup&quot;">​</a></h2><p>The server exposes an encrypted backup API. The passphrase must be at least 12 characters; it is stretched with scrypt (N=32768, r=8, p=1), and the archive uses AES-256-GCM.</p><p>Create a backup:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317/api/backups</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;content-type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passphrase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">replace-with-a-long-passphrase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span></code></pre></div><p>List and download:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317/api/backups</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -OJ</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317/api/backups/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/download</span></span></code></pre></div><p>Restore from a stored archive:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:4317/api/backups/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">i</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/restore</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;content-type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">passphrase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">replace-with-a-long-passphrase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">}&quot;</span></span></code></pre></div><p>Restore writes a temporary SQLite file, checks <code>user_version</code>, schema, and <code>integrity_check</code>, rebuilds projections, then copies in a transaction; failure rolls back. The scheduler stops during restore and restarts afterward if it was running and the global kill switch is not active.</p><div class="warning custom-block"><p class="custom-block-title">A recoverable database is not a portable artifact archive</p><p>The backup does not include artifact bodies, workspaces, source bodies, outbox attachments, desktop screenshots, or external service data. After restore, tasks may reappear while artifact files still need separate verification. For a complete archive, also copy <code>.hearth/artifacts/</code>, <code>.hearth/workspaces/</code>, <code>.hearth/sources/</code>, <code>.hearth/outbox/</code>, and <code>eval/runs/</code>.</p></div><h2 id="global-stop-and-kill-switch" tabindex="-1">Global stop and kill switch <a class="header-anchor" href="#global-stop-and-kill-switch" aria-label="Permalink to &quot;Global stop and kill switch&quot;">​</a></h2><p>After <code>POST /api/security/kill-switch</code> enables the global stop:</p><ul><li>The scheduler stops and desktop sessions freeze.</li><li>Pending approvals are cancelled and related tasks become recoverable.</li><li>The scheduler does not auto-start when the service restarts.</li><li>A security audit record is written.</li></ul><p>Clearing the kill switch does not automatically restart the scheduler; call <code>POST /api/system/start</code> or restart the service explicitly.</p><h2 id="health-and-maintenance" tabindex="-1">Health and maintenance <a class="header-anchor" href="#health-and-maintenance" aria-label="Permalink to &quot;Health and maintenance&quot;">​</a></h2><ul><li><code>GET /api/health</code>: uptime, memory, disk, schema, task counts, scheduler, approvals, kill switch, and last maintenance.</li><li><code>GET /api/maintenance</code>: last maintenance result.</li><li><code>POST /api/maintenance/run</code>: run maintenance manually.</li><li><code>GET /api/diagnostics</code>: download redacted diagnostics without paths, keys, or environment secrets.</li></ul><p>Maintenance runs every six hours after startup. It clears expired approvals, recovers interrupted tasks, and deletes expired leases, desktop commands, screenshots, pairings, and temporary files. It does not delete tasks, memory, or artifacts.</p>`,21)])])}const u=s(n,[["render",d]]);export{k as __pageData,u as default};
